import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.BzGQ_3Jc.js";const l=JSON.parse('{"title":"13 FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"13_FAQ.md","filePath":"13_FAQ.md","lastUpdated":1787816986000}'),n={name:"13_FAQ.md"};function t(c,o,i,s,p,h){return r(),a("div",null,[...o[0]||(o[0]=[d('<h1 id="_13-faq" tabindex="-1">13 FAQ <a class="header-anchor" href="#_13-faq" aria-label="Permalink to &quot;13 FAQ&quot;">​</a></h1><blockquote><p>文档版本：1.1.5</p></blockquote><hr><h2 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h2><p><strong>必须调 <code>setPrivacyUserAgree(true)</code> 才能出广告吗？</strong><br> 不必。默认就是开。只在用户明确拒绝时调 <code>false</code>。详见 <a href="./04_初始化与隐私">04</a>。</p><p><strong>可以在子进程 Init 吗？</strong><br> Android 不行，必须主进程。iOS 在 <code>didFinishLaunching</code>。</p><p><strong>Init 还没回调就 Load？</strong><br> 不要。尤其是冷启动开屏，等 Init 成功。</p><p><strong>App ID 写空会闪退吗？</strong><br> 不会。空 AppId / 空 Context 走 <code>onFailed</code>（1001）。</p><p><strong>对象已经 <code>onDestroy</code> 再 Load / Show？</strong><br> 会收到失败回调（1001），不会再哑巴返回。激励/插屏正在展示时再 Show，若上一页已销毁或超过 10 分钟，会先解开锁再试。<code>onDestroy</code> 不清广告池，要清缓存请再调 <code>clearCache()</code>。</p><p><strong>怎么拿到当前广告信息？</strong><br> 各格式都有 <code>getAdInfo()</code>，对应最近一次 Load 成功或即将 Show 的 <code>TDAdInfo</code>。原生自渲染也可在这里读 <code>renderType</code> / <code>nativeMaterial</code>。</p><hr><h2 id="填充与设备标识" tabindex="-1">填充与设备标识 <a class="header-anchor" href="#填充与设备标识" aria-label="Permalink to &quot;填充与设备标识&quot;">​</a></h2><p><strong>JinDai / AdGain 为什么没广告？</strong><br> 这两家依赖 OAID（Android）或 IDFA（iOS）。四门未开、OAID 还没回写、或用户拒绝 ATT，都可能无填充。见 <a href="./04_初始化与隐私">04</a>。</p><p><strong>刚 Init 完就 Load，OAID 还是空的？</strong><br> 采集是异步的。等标识回写后再 Load，不要在 Init 当帧立刻请求。</p><p><strong>必须接 MSA / ATTracking？</strong><br> 要接 JinDai、AdGain 等依赖设备标识的源时，需要。其它源按该平台文档。</p><hr><h2 id="广告展示" tabindex="-1">广告展示 <a class="header-anchor" href="#广告展示" aria-label="Permalink to &quot;广告展示&quot;">​</a></h2><p><strong>Load 成功了为什么 Show 说没缓存？</strong><br> 原生后台若配的是自渲染，客户端却当模板 Show（或反过来）会失败。以 <code>renderType</code> 为准。也可能上一轮已 Show 过，需重新 Load。</p><p><strong>原生 Load 完容器里已经有字？</strong><br> 那是宿主在 <code>onAdLoaded</code> 里拼装了。SDK 不会自动 Show。把拼装挪到点 Show 时。也可以用 <code>getAdInfo()</code> 取素材，或走模板 Show（Android <code>layoutRes</code> / iOS nib）。</p><p><strong>自渲染只有图标和字、点了没反应？</strong><br> 缺主图：没把 <code>imageUrl</code> 填进带 <code>td_image</code> 的 ImageView。<br> 点不动：Android 控件要 <code>clickable</code>；iOS <code>UILabel</code> 要 <code>userInteractionEnabled=YES</code>；并打上 TAG。</p><p><strong>JinDai Banner 被压扁？</strong><br> 官方高度自适应。容器不要锁 50dp，建议 ≥200dp。见 <a href="./08_横幅广告">08</a>。</p><p><strong>开屏容器必须全屏吗？</strong><br> 是。过小会无法展示。Android 用 <code>INVISIBLE</code> 不要 <code>GONE</code>。</p><hr><h2 id="集成" tabindex="-1">集成 <a class="header-anchor" href="#集成" aria-label="Permalink to &quot;集成&quot;">​</a></h2><p><strong>插屏报 adapter 缺失，激励却正常？</strong><br> 激励和插屏是不同模块。Android / iOS 都要单独加对应 TD 模块和三方 SDK。见 <a href="./02_Android集成">02</a> / <a href="./03_iOS集成">03</a>。</p><p><strong>AdGain 没有 Banner？</strong><br> 该平台无 Banner API，会 <code>formatUnsupported</code>。换源或不要给 Banner 位配 AdGain。</p><p><strong>iOS 能跑但编译仍有链接警告？</strong><br> 核对 ATS、<code>-ObjC</code>、LiteMob 版本与 rpath。见 <a href="./03_iOS集成">03</a>。</p><hr><h2 id="回调与重试" tabindex="-1">回调与重试 <a class="header-anchor" href="#回调与重试" aria-label="Permalink to &quot;回调与重试&quot;">​</a></h2><p><strong>失败了立刻再 Load？</strong><br> 不要。必须重试时自己控制间隔。上一轮未结束会走 <code>onAdIsLoading</code>。</p><p><strong><code>onAdReward</code> 和 <code>onAdClosed</code> 哪个先？</strong><br> 通常先 Reward 再 Close。以实际回调为准，发奖只写在 <code>onAdReward</code>。</p><p><strong>错误码在哪查？</strong><br><a href="./11_回调与错误码">11 回调与错误码</a>。</p>',32)])])}const A=e(n,[["render",t]]);export{l as __pageData,A as default};
